const { existsSync } = await import('node:fs');
const pdfPath = process.env.PDF_PATH;
if (!pdfPath || !existsSync(pdfPath)) { throw new Error('Missing or invalid pdf_path'); }
globalThis.pdfPath = pdfPath;

const { PDFDocument } = await import('pdf-lib');
const { pdflibAddPlaceholder } = await import('@signpdf/placeholder-pdf-lib');
const { readFile, writeFile } = await import('node:fs').then(m => m.promises);
const existingBytes = await readFile(globalThis.pdfPath);
const pdfDoc = await PDFDocument.load(existingBytes);
await pdflibAddPlaceholder({ pdfDoc });
const pdfBytes = await pdfDoc.save();
const outPath = '/tmp/output.pdf';
await writeFile(outPath, pdfBytes);
globalThis.outputPath = outPath;
